// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address alice = address(0x1);

    function setUp() public { 
        c = new C(); 
        vm.deal(alice, 1e30);
    }

    function testFuzz_property(address caller, uint256 amount) public {
        vm.assume(caller != address(0));
        vm.assume(amount <= address(this).balance);
        vm.deal(caller, amount);
        vm.prank(caller);
        uint256 balanceBefore = address(c).balance;
        uint256 userBalBefore = c.getBalance(caller);

        // Call addToBalance
        c.addToBalance{value: amount}();

        uint256 balanceAfter = address(c).balance;
        uint256 userBalAfter = c.getBalance(caller);

        // The contract balance should equal sum of all user balances
        // Since we only modified caller's balance, total user balance change = userBalAfter - userBalBefore
        // and contract balance change = balanceAfter - balanceBefore = amount (since no overflow)
        // We check the invariant: contract balance = sum of all user balances
        // For simplicity, we check that the change in contract balance equals the change in caller's balance
        assertTrue(balanceAfter - balanceBefore == userBalAfter - userBalBefore);
    }
}
